def permanent(matrix):
    n = len(matrix)
    memo = {}
    def solve(mask, row):
        if row == n:
            return 1
        if (mask, row) in memo:
            return memo[(mask, row)]
        res = 0
        for col in range(n):
            if not (mask & (1 << col)) and matrix[row][col] == 1:
                res += solve(mask | (1 << col), row + 1)
        memo[(mask, row)] = res
        return res
    return solve(0, 0)

