def ryser_permanent(matrix):
    n = len(matrix)
    total_perm = 0
    for i in range(1 << n):
        subset_sum = np.zeros(n)
        subset_size = 0
        for j in range(n):
            if (i >> j) & 1:
                subset_size += 1
                subset_sum += matrix[:, j]

        prod = np.prod(subset_sum)
        if (n - subset_size) % 2 == 1:
            total_perm -= prod
        else:
            total_perm += prod
    return total_perm

