def solve():
    n = 16
    # S[i] is the set of allowed columns for row i
    S = []
    for i in range(n):
        S.append({(i - j) % n for j in range(4)})

    # dp[mask] = number of ways to fill the first 'r' rows using columns in 'mask'
    # where 'r' is the number of set bits in 'mask'
    dp = {0: 1}

    # We can also use dp[r][mask] but that's not necessary
    # We'll iterate through each row and update the mask
    for r in range(n):
        new_dp = {}
        for mask, count in dp.items():
            for col in S[r]:
                if not (mask & (1 << col)):
                    new_mask = mask | (1 << col)
                    new_dp[new_mask] = new_dp.get(new_mask, 0) + count
        dp = new_dp

    return sum(dp.values())

