import itertools

def solve_small(N, rounds):
    count = 0
    for p in itertools.permutations(range(N)):
        current_guests = [{'id': i, 'tag': p[i]} for i in range(N)]
        for _ in range(rounds):
            remaining = [g for g in current_guests if g['tag'] != g['id']]
            if not remaining:
                break
            for j in range(len(remaining)):
                remaining[j]['tag'] = remaining[(j-1) % len(remaining)]['tag']
            current_guests = remaining
        if len(current_guests) > 0:
            count += 1
    return count

